(() => {
  const store = {
    get(key, fallback) { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; } catch { return fallback; } },
    set(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { return false; } }
  };
  const routeData = {
    meghalaya: {
      name: 'Meghalaya', title: 'Meghalaya, with room to breathe.', stops: 'Shillong & Sohra', image: 'photo-1464822759023-fed622ff2c3b',
      match: 'EASY PACE · NATURE · FIVE DAYS', summary: 'A gentle loop from Guwahati to Shillong and Sohra, with a slower first day and choices for the more active ones.',
      days: [
        ['Arrive & settle','Guwahati to Shillong','Arrive, take the road to Shillong, and keep the evening free. A slow landing helps the rest of the trip feel less rushed.',['Transfer day','Easy evening','Road time to verify']],
        ['Shillong, slowly','A little city, then an open afternoon','Pick one neighbourhood or viewpoint, then leave the rest of the day loose for a café, a market, or a much-needed nap.',['Choose one stop','Food & local life']],
        ['The road to Sohra','Take the scenic route south','Pause at one or two viewpoints on the way. Keep the stops flexible rather than turning the drive into a checklist.',['Scenic transfer','Rain can change the plan']],
        ['Your kind of outdoors','Choose a walk—or choose not to','Make this the flexible day: an easy viewpoint option or a longer guided walk, depending on conditions and how you feel.',['Optional activity','Effort varies','Local guide may help']],
        ['Return with a buffer','Sohra back to Guwahati','Keep the final transfer unhurried and allow a sensible buffer before your onward journey.',['Transfer day','Check departure time']]
      ]
    },
    ladakh: {
      name: 'Ladakh', title: 'Ladakh, with time to land.', stops: 'Leh & the Indus valley', image: 'photo-1501785888041-af3ef285b470',
      match: 'MOUNTAIN AIR · SLOW START · FIVE DAYS', summary: 'A deliberately gentle first draft based around Leh, with room to acclimatise and a reminder to verify altitude, season, permits and current conditions.',
      days: [
        ['Arrive & rest','A very soft first day in Leh','Keep plans close to your stay and allow proper time to acclimatise. Confirm health and travel guidance before choosing any activity.',['Arrival day','Rest first','Altitude matters']],
        ['Stay close','A quiet day around Leh','Keep the outing low-effort and local. Let your energy, not a checklist, set the pace.',['Low effort','Flexible']],
        ['Find your rhythm','One nearby place, with buffer','Only add an outing after checking how you feel and getting current local advice.',['Optional outing','Conditions to verify']],
        ['The Indus valley','Choose a short scenic drive','Keep stops limited and the day adaptable. Check road access, permits and weather before setting off.',['Road day','Verify locally']],
        ['Leave room to return','A gentle final day','Protect the transfer window and keep the rest of the day open.',['Transfer buffer','Easy finish']]
      ]
    },
    kerala: {
      name: 'Kerala', title: 'Kerala, at water level.', stops: 'Kochi & the backwaters', image: 'photo-1602216056096-3b40cc0c9944',
      match: 'SLOW WATER · FOOD · FIVE DAYS', summary: 'A slower coastal and backwater idea with time between transfers. The precise base and boat options depend on dates and partner availability.',
      days: [
        ['Arrive & settle','A first evening in Kochi','Check in, find dinner nearby and let the first evening stay easy.',['Arrival day','Food nearby']],
        ['Old lanes, your pace','A little Fort Kochi','Pick one neighbourhood walk and leave an open hour for a café, gallery or rest.',['Easy walk','Local food']],
        ['Follow the water','Transfer toward the backwaters','Choose a stay and transfer only after checking the route and live availability. Keep arrival plans light.',['Transfer day','Confirm partner details']],
        ['A slow boat morning','Choose a water experience','Compare trip length, group size and operating details before you decide. The afternoon can stay yours.',['Optional activity','Slow morning']],
        ['Coffee before you go','Return with room to spare','Keep the return journey matched to your onward departure, with a sensible buffer.',['Transfer buffer','Flexible finish']]
      ]
    },
    rajasthan: {
      name: 'Rajasthan', title: 'Rajasthan, after the rush.', stops: 'Jaipur & nearby', image: 'photo-1477587458883-47145ed94245',
      match: 'OLD STREETS · FOOD · FIVE DAYS', summary: 'A city-led route with early starts for outdoor visits, slower afternoons, and choices that can suit a family group.',
      days: [
        ['Arrive & settle','A calm first evening in Jaipur','Check in, get oriented and keep the first evening close by.',['Arrival day','Easy evening']],
        ['A morning outdoors','One historic site, early','Choose one visit before the warmer part of the day and check current opening details.',['Culture','Check opening times']],
        ['Local life & lunch','A food-led neighbourhood day','Follow a local recommendation and leave time between stops.',['Food','Flexible pace']],
        ['Choose your own detour','A nearby place or a rest day','Keep this day optional. A rest or shorter outing may suit the group better.',['Optional outing','Family pace']],
        ['One last chai','A flexible final morning','Leave a little room for one last stop, then travel with a buffer.',['Transfer buffer','Easy finish']]
      ]
    }
  };
  const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const toast = document.createElement('div'); toast.className = 'global-toast'; toast.setAttribute('role','status'); toast.setAttribute('aria-live','polite'); document.body.append(toast);
  let toastTimer; function notify(message) { toast.textContent=message; toast.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>toast.classList.remove('visible'),2400); }
  const page = location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.primary-nav a').forEach(link=>{if(link.getAttribute('href')===page)link.setAttribute('aria-current','page')});
  const menuButton=document.querySelector('.menu-toggle'), nav=document.querySelector('.primary-nav');
  if(menuButton&&nav)menuButton.addEventListener('click',()=>{const opened=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(opened));menuButton.textContent=opened?'×':'☰'});
  const countSaved=()=>{const trips=store.get('vayanai.savedTrips',[]);document.querySelectorAll('.saved-count').forEach(el=>{el.hidden=!trips.length;el.textContent=String(trips.length)})};countSaved();
  const observer=('IntersectionObserver'in window)?new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1}):null;
  document.querySelectorAll('.reveal').forEach(el=>observer?observer.observe(el):el.classList.add('visible'));
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const hero=document.querySelector('.hero-photo');if(hero&&innerWidth>760)window.addEventListener('scroll',()=>hero.style.transform=`translateY(${scrollY*.07}px) scale(1.04)`,{passive:true})}

  document.querySelectorAll('.prompt-suggestion').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById('tripPrompt');if(input){input.value=button.dataset.prompt;input.focus()}}));
  document.querySelectorAll('#budgetOptions .select-chip').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('#budgetOptions .select-chip').forEach(x=>{x.classList.toggle('is-selected',x===button);x.setAttribute('aria-pressed',String(x===button))})}));
  document.querySelectorAll('#interestOptions .select-chip').forEach(button=>button.addEventListener('click',()=>{const active=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(active));button.classList.toggle('is-selected',active)}));
  const form=document.getElementById('tripForm');
  if(form)form.addEventListener('submit',event=>{event.preventDefault();const prompt=document.getElementById('tripPrompt').value.trim();const origin=document.getElementById('origin').value;const interests=[...document.querySelectorAll('#interestOptions .select-chip[aria-pressed="true"]')].map(x=>x.textContent);const budget=document.querySelector('#budgetOptions .select-chip[aria-pressed="true"]')?.textContent||'Keep it flexible';const checkboxes=[...form.querySelectorAll('.more-fields input:checked')].map(x=>x.value);const brief={prompt,origin,when:document.getElementById('when').value,party:document.getElementById('party').value,duration:document.getElementById('duration').value,interests,budget,accessibility:checkboxes,routeKey:inferRoute(prompt,interests)};store.set('vayanai.lastBrief',brief);const overlay=document.createElement('div');overlay.className='planning-overlay';overlay.innerHTML='<div class="planning-card"><div class="planning-symbol">व</div><span>VAYU IS SHAPING A SAMPLE ROUTE</span><h2>Putting your priorities<br>in the right order.</h2><div class="planning-progress"><i></i></div><p>Separating must-haves from nice-to-haves…</p><small>Preview mode · no live travel data checked</small></div>';document.body.append(overlay);requestAnimationFrame(()=>overlay.classList.add('show'));setTimeout(()=>location.href='trip.html',1350)});
  function inferRoute(prompt, interests=[]){const text=(prompt+' '+interests.join(' ')).toLowerCase();if(/rajasthan|jaipur|heritage|history|fort|palace/.test(text))return'rajasthan';if(/kerala|backwater|coast|beach|water|konkan/.test(text))return'kerala';if(/ladakh|leh|mountain|altitude|himachal|himalaya/.test(text))return'ladakh';return'meghalaya'}

  const saveButton=document.getElementById('saveTrip');
  if(saveButton){const brief=store.get('vayanai.lastBrief',{});if(brief.origin)document.getElementById('tripOriginLabel').textContent=brief.origin;const key=routeData[brief.routeKey]?brief.routeKey:'meghalaya';const route=routeData[key];const heroTitle=document.querySelector('.trip-hero h1');if(key!=='meghalaya'){heroTitle.innerHTML=`${escapeHtml(route.name)},<br><em>${escapeHtml(route.title.split(', ').slice(1).join(', '))}</em>`;document.querySelector('.trip-hero-copy>p').textContent=route.summary;document.querySelector('.trip-hero-image').style.backgroundImage=`linear-gradient(90deg,#09120ff1 0%,#101a19ab 48%,#101a1932 100%),linear-gradient(0deg,#101a19e0,transparent 72%),url('https://images.unsplash.com/${route.image}?auto=format&fit=crop&w=1850&q=86')`;document.querySelector('.route-match').innerHTML=`MATCH NOTES &nbsp; <span>✳</span> ${escapeHtml(route.match)}`;document.querySelectorAll('.trip-meta')[0].children[2].innerHTML=`⌖ &nbsp; ${escapeHtml(route.stops)}`;document.querySelector('.map-caption').textContent=`ROUTE SHAPE · ${route.name.toUpperCase()} · NOT NAVIGATION`;const list=document.querySelector('.itinerary-days');list.innerHTML=route.days.map((d,i)=>`<article class="itinerary-day"><div class="day-number">${String(i+1).padStart(2,'0')}</div><div class="day-info"><div class="day-top"><span>${escapeHtml(d[0].toUpperCase())}</span><button class="day-more" aria-label="Show day ${i+1} details" aria-expanded="false">+</button></div><h3>${escapeHtml(d[1])}</h3><p>${escapeHtml(d[2])}</p><div class="day-tags">${d[3].map(tag=>`<span>${escapeHtml(tag)}</span>`).join('')}</div><div class="day-extra" hidden><b>Planning note</b><p>Confirm current access, travel times and provider details before finalising this day.</p><button class="ask-day" data-question="Help me refine ${escapeHtml(d[1])}.">Ask Vayu about this day ↗</button></div></div></article>`).join('')}
    const saved=store.get('vayanai.savedTrips',[]);const isSaved=saved.some(x=>x.id===key);saveButton.querySelector('span').textContent=isSaved?'♥':'♡';saveButton.classList.toggle('is-saved',isSaved);saveButton.addEventListener('click',()=>{let trips=store.get('vayanai.savedTrips',[]);if(trips.some(x=>x.id===key)){trips=trips.filter(x=>x.id!==key);notify('Removed from your saved trips.')}else{trips.unshift({id:key,title:route.title,origin:brief.origin||'Mumbai',duration:brief.duration||'About five days',budget:brief.budget||'₹45–75k',image:route.image,updated:new Date().toISOString()});notify('Saved to your trip shelf.')}store.set('vayanai.savedTrips',trips);const nowSaved=trips.some(x=>x.id===key);saveButton.querySelector('span').textContent=nowSaved?'♥':'♡';saveButton.classList.toggle('is-saved',nowSaved);countSaved()})}
  document.addEventListener('click',event=>{const more=event.target.closest('.day-more');if(more){const extra=more.closest('.day-info').querySelector('.day-extra');const open=extra.hidden;extra.hidden=!open;more.setAttribute('aria-expanded',String(open));more.textContent=open?'−':'+';return}const question=event.target.closest('[data-question]');if(question){openChat();sendSample(question.dataset.question)}});
  const paceAll=document.getElementById('paceAll');if(paceAll)paceAll.addEventListener('click',()=>{const gentler=paceAll.dataset.gentler!=='true';paceAll.dataset.gentler=String(gentler);paceAll.textContent=gentler?'Keep original pace ↑':'Make days gentler ↓';document.querySelectorAll('.day-tags').forEach((tags,i)=>{if(gentler){tags.dataset.original=tags.innerHTML;if(i===0)tags.innerHTML='<span>Transfer only</span><span>Rest first</span>';else if(i===3)tags.innerHTML='<span>Optional activity</span><span>Easy alternative</span>';else if(i===4)tags.innerHTML='<span>Transfer buffer</span><span>No extra stops</span>'}else if(tags.dataset.original){tags.innerHTML=tags.dataset.original}});notify(gentler?'Gentler options highlighted.':'Original pacing restored.')});
  document.querySelectorAll('.result-tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.result-tab').forEach(tab=>{const selected=tab===button;tab.classList.toggle('active',selected);tab.setAttribute('aria-selected',String(selected))});document.querySelectorAll('.tab-panel').forEach(panel=>{panel.hidden=panel.id!==`panel-${button.dataset.tab}`;panel.classList.toggle('active',!panel.hidden)})}));

  const drawer=document.getElementById('chatDrawer'),backdrop=document.getElementById('chatBackdrop');function openChat(){if(!drawer)return;drawer.classList.add('open');backdrop.classList.add('open');drawer.setAttribute('aria-hidden','false');document.getElementById('chatInput')?.focus()}function closeChat(){if(!drawer)return;drawer.classList.remove('open');backdrop.classList.remove('open');drawer.setAttribute('aria-hidden','true')}
  document.getElementById('openChat')?.addEventListener('click',openChat);document.getElementById('askVayuTop')?.addEventListener('click',openChat);document.getElementById('closeChat')?.addEventListener('click',closeChat);backdrop?.addEventListener('click',closeChat);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeChat()});
  function sendSample(text){const messages=document.getElementById('chatMessages');if(!messages)return;const user=document.createElement('div');user.className='chat-bubble user';user.textContent=text;messages.append(user);const answer=document.createElement('div');answer.className='chat-bubble bot';const lower=text.toLowerCase();if(lower.includes('drive')||lower.includes('road'))answer.textContent='For a gentler version, keep one base change and treat the scenic stops as optional. The real route times and current road conditions would need checking before you settle dates.';else if(lower.includes('food'))answer.textContent='A food-led day could focus on one neighbourhood and a local host, with fewer viewpoint stops. In a live plan, I’d show the partner and source behind each suggestion.';else if(lower.includes('easy')||lower.includes('walk')||lower.includes('active'))answer.textContent='We can make the walk optional and add an easier viewpoint day. Trail access, steps and current conditions should be checked for the exact route.';else answer.textContent='I can adjust the sample route’s pace, interests or transfer balance. A live Vayu plan would check current sources before presenting route facts.';const note=document.createElement('small');note.textContent='Preview response · not live AI or current travel data';answer.append(note);messages.append(answer);messages.scrollTop=messages.scrollHeight}
  document.getElementById('chatForm')?.addEventListener('submit',event=>{event.preventDefault();const input=document.getElementById('chatInput');const value=input.value.trim();if(value){sendSample(value);input.value=''}});

  document.querySelectorAll('.interest-link').forEach(button=>button.addEventListener('click',()=>{const interest=button.dataset.interest;const brief=store.get('vayanai.lastBrief',{});brief.interests=[...new Set([...(brief.interests||[]),interest])];store.set('vayanai.lastBrief',brief);notify(`${interest} added to your planning idea.`);setTimeout(()=>location.href='plan.html',500)}));
  const savedList=document.getElementById('savedTrips'),empty=document.getElementById('savedEmpty');if(savedList&&empty){const render=()=>{const trips=store.get('vayanai.savedTrips',[]);countSaved();empty.hidden=Boolean(trips.length);savedList.innerHTML=trips.map(trip=>{const data=routeData[trip.id]||routeData.meghalaya;return `<article class="saved-card" data-id="${escapeHtml(trip.id)}"><div class="saved-card-image" style="background-image:url('https://images.unsplash.com/${escapeHtml(trip.image||data.image)}?auto=format&fit=crop&w=650&q=82')"></div><div class="saved-card-content"><span>TRIP IDEA · ${escapeHtml(trip.origin||'INDIA')}</span><h3>${escapeHtml(trip.title||data.title)}</h3><p>${escapeHtml(trip.duration||'About five days')} · ${escapeHtml(trip.budget||'Flexible comfort')}</p><span class="saved-status">NOT BOOKED · IDEA ONLY</span><div class="saved-card-actions"><a href="trip.html" data-open-trip="${escapeHtml(trip.id)}">Open the route ↗</a><button type="button" data-remove-trip="${escapeHtml(trip.id)}">Remove</button></div></div></article>`}).join('')};render();savedList.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-trip]');if(remove){const id=remove.dataset.removeTrip;store.set('vayanai.savedTrips',store.get('vayanai.savedTrips',[]).filter(x=>x.id!==id));render();notify('Trip idea removed.');return}const open=event.target.closest('[data-open-trip]');if(open){const trip=store.get('vayanai.savedTrips',[]).find(x=>x.id===open.dataset.openTrip);if(trip)store.set('vayanai.lastBrief',{origin:trip.origin||'Mumbai',duration:trip.duration||'About five days',budget:trip.budget||'₹45–75k',routeKey:trip.id,interests:[]})}})}
})();
